// C. Storyboard Generation Studio
const VeoGenerator = () => {
  const { state, dispatch } = useContext(AppContext);
  
  const ANGLES = [
    { id: 'wide', label: 'Wide Shot', suffix: 'Wide angle establishing shot, full body, environmental context, cinematic lighting.' },
    { id: 'medium', label: 'Medium Shot', suffix: 'Medium shot, waist up, focus on character pose and attire, neutral background.' },
    { id: 'closeup', label: 'Close Up', suffix: 'Close up, face detail, emotional expression, shallow depth of field.' },
    { id: 'low', label: 'Low Angle', suffix: 'Low angle shot looking up, heroic perspective, dynamic composition.' },
    { id: 'high', label: 'High Angle', suffix: 'High angle shot looking down, establishing vulnerability or scale.' },
    { id: 'dutch', label: 'Dutch Angle', suffix: 'Tilted Dutch angle shot, dynamic action, intense atmosphere.' },
    { id: 'overhead', label: 'Overhead', suffix: 'Direct top-down bird\'s eye view, geometric composition, layout context.' },
    { id: 'ots', label: 'Over-The-Shoulder', suffix: 'Over-the-shoulder perspective looking at subject, conversational depth.' },
    { id: 'side', label: 'Side Profile', suffix: 'Side profile view, dramatic lighting, strong silhouette, 90-degree angle.' }
  ];

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        dispatch({ type: 'SET_STORYBOARD_SOURCE', payload: { url: ev.target?.result as string } });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!state.storyboardSource) return;
    
    // 1. Setup Grid
    const newGenerations: StoryboardGeneration[] = ANGLES.map(a => ({
        id: a.id,
        angle: a.label,
        promptSuffix: a.suffix,
        url: null,
        status: 'pending'
    }));
    
    dispatch({ type: 'SET_STORYBOARD_GENERATIONS', payload: newGenerations });
    dispatch({ type: 'SET_PROCESSING', payload: true });

    // 2. Parallel Generation
    // Emphasize 3D rendering and style matching to prevent 2D/sketch fallbacks
    const corePrompt = "High-fidelity 3D render. MATCH THE REFERENCE STYLE EXACTLY. Use standard surface scattering, ray-traced lighting, and soft shadows. Identical character design and color palette. Final production quality. NOT A SKETCH.";
    
    // Used for parallel tracking
    const promises = ANGLES.map(async (angle) => {
        try {
            const fullPrompt = `${corePrompt} ${angle.suffix}`;
            
            // Use the source image as a reference
            const url = await GeminiService.generateImage(
                fullPrompt,
                state.apiKey,
                state.model,
                [{ url: state.storyboardSource!.url, label: "Master Style Reference" }],
                { aspectRatio: '16:9' }
            );
            
            // Success update
            dispatch({ 
                type: 'UPDATE_STORYBOARD_GENERATION', 
                payload: { id: angle.id, url, status: 'success' } 
            });
            
        } catch (err: any) {
            console.error(`Generation failed for ${angle.id}`, err);
            dispatch({ 
                type: 'UPDATE_STORYBOARD_GENERATION', 
                payload: { id: angle.id, status: 'error' } 
            });
            dispatch({ type: 'ADD_LOG', payload: { message: `Failed to gen ${angle.label}: ${err.message}`, type: 'error' } });
        }
    });

    // Wait for all to finish so we can turn off global processing indicator
    await Promise.all(promises);
    dispatch({ type: 'SET_PROCESSING', payload: false });
  };

  return (
    <div className="h-full bg-[#0f0f11] p-8 overflow-y-auto">
      <div className="max-w-[1600px] mx-auto space-y-8 pb-12">
        
        {/* Header */}
        <div className="flex justify-between items-end border-b border-gray-800 pb-6">
          <div className="flex items-center gap-3">
            <Clapperboard className="w-8 h-8 text-blue-500" />
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase">Storyboard Studio</h2>
              <p className="text-gray-500 font-mono text-xs uppercase tracking-widest">Multi-Angle Scene Generation</p>
            </div>
          </div>
          <div>
             <button 
                onClick={() => dispatch({ type: 'CLEAR_STAGE' })}
                className="text-[10px] font-bold text-gray-500 hover:text-red-500 uppercase tracking-widest transition-colors flex items-center gap-2"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Reset Studio
              </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           
           {/* LEFT COLUMN: SOURCE INPUT */}
           <div className="lg:col-span-3 space-y-6">
              
              <div className={`relative aspect-[3/4] rounded-2xl border-2 border-dashed overflow-hidden group transition-all ${state.storyboardSource ? 'border-blue-500/50 bg-black' : 'border-gray-800 bg-[#18181b] hover:border-gray-700'}`}>
                 
                 {state.storyboardSource ? (
                    <>
                        <img src={state.storyboardSource.url} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-6">
                            <span className="text-xs font-mono text-gray-300">Master Reference</span>
                        </div>
                    </>
                 ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 group-hover:text-gray-400">
                        <ImageIcon className="w-12 h-12 mb-4 opacity-50" />
                        <span className="text-xs font-black uppercase tracking-widest">Upload Keyframe</span>
                    </div>
                 )}
                 
                 <input 
                    type="file" 
                    onChange={handleUpload} 
                    className="absolute inset-0 opacity-0 cursor-pointer" 
                    accept="image/*" 
                    title="Upload Master Shot"
                 />
              </div>

              <div className="space-y-2">
                  <div className="flex justify-between items-center text-[10px] uppercase font-bold text-gray-500 tracking-widest px-2">
                       <span>Generation Queue</span>
                       <span>{state.model}</span>
                  </div>
                  <button 
                    onClick={handleGenerate}
                    disabled={!state.storyboardSource || state.isProcessing}
                    className="w-full py-4 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-black text-xs uppercase tracking-[0.2em] rounded-xl shadow-lg shadow-blue-500/20 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                  >
                    {state.isProcessing ? <RotateCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    {state.isProcessing ? 'Rendering...' : 'Generate 9 Angles'}
                  </button>
              </div>
              
              <div className="bg-blue-500/5 border border-blue-500/20 p-4 rounded-xl">
                 <p className="text-[10px] text-blue-400 leading-relaxed font-mono">
                    <strong>TIP:</strong> For best style consistency, ensure the master keyframe is high resolution. The AI will attempt to clone the lighting and render style for all 6 angles.
                 </p>
              </div>

           </div>

           {/* RIGHT COLUMN: OUTPUT GRID */}
           <div className="lg:col-span-9">
              <div className="grid grid-cols-2 xl:grid-cols-3 gap-4">
                 {/* Placeholders or Results */}
                 {(state.storyboardGenerations.length === 0 ? ANGLES : state.storyboardGenerations).map((item: any) => {
                     const isGen = 'status' in item;
                     const status = isGen ? item.status : 'idle';
                     const label = isGen ? item.angle : item.label;
                     const suffix = isGen ? item.promptSuffix : item.suffix;

                     return (
                         <div key={item.id} className="aspect-video bg-[#09090b] rounded-xl border border-gray-800 overflow-hidden relative group">
                            
                            {/* Content */}
                            {status === 'success' && item.url ? (
                                <img src={item.url} className="w-full h-full object-cover" />
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center p-6 text-center">
                                    {status === 'pending' ? (
                                        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                                    ) : (
                                        <Film className="w-8 h-8 text-gray-800 mb-2" />
                                    )}
                                    <span className="text-[10px] font-mono text-gray-600 uppercase tracking-widest">
                                        {status === 'pending' ? 'Rendering Pixel Data...' : (status === 'error' ? 'Enhancement Failed' : 'Waiting for Input')}
                                    </span>
                                </div>
                            )}

                            {/* Label Overlay */}
                            <div className="absolute top-0 left-0 p-3 w-full flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent">
                                <span className="text-[10px] font-black text-white uppercase tracking-widest shadow-black drop-shadow-md">
                                    {label}
                                </span>
                                {status === 'success' && (
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button className="p-1.5 bg-black/50 hover:bg-white text-white hover:text-black rounded-lg transition-colors">
                                            <Copy className="w-3 h-3" onClick={() => {
                                                if (item.url) navigator.clipboard.writeText(item.url);
                                            }} />
                                        </button>
                                    </div>
                                )}
                            </div>
                            
                            {/* Description Overlay (Bottom) */}
                            <div className="absolute bottom-0 left-0 p-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                <p className="text-[9px] text-gray-400 font-mono shadow-black drop-shadow-md leading-tight max-w-[80%]">
                                    {suffix}
                                </p>
                            </div>

                        </div>
                     );
                 })}
              </div>
           </div>

        </div>
      </div>
    </div>
  );
};

// B. Wardrobe Studio Component
const WardrobeStudio = () => {
  const { state, dispatch } = useContext(AppContext);
  const [activeTab, setActiveTab] = useState<'designer' | 'library'>('designer');
  const [designerPrompt, setDesignerPrompt] = useState("");
  const [designerImage, setDesignerImage] = useState<string | null>(null);
  const [designerMask, setDesignerMask] = useState<string | null>(null);
  const [selectedCostume, setSelectedCostume] = useState<WardrobeItem | null>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<CastMember | null>(null);
  const [fittedImage, setFittedImage] = useState<string | null>(null);
  const [tryOnNote, setTryOnNote] = useState("");
  const [tryOnMask, setTryOnMask] = useState<string | null>(null);

  // Try-On Removal State
  const [removeTryOnBg, setRemoveTryOnBg] = useState(false);
  const [tryOnAiMaskActive, setTryOnAiMaskActive] = useState(true);
  const [tryOnTolerance, setTryOnTolerance] = useState(15);
  const [tryOnSpillSuppression, setTryOnSpillSuppression] = useState(100); 
  const [tryOnMaskSoftening, setTryOnMaskSoftening] = useState(1.5);
  const [tryOnInvertBg, setTryOnInvertBg] = useState(false);
  const [matteErosion, setMatteErosion] = useState(1); // 0-5 pixels erosion
  const tryOnImgRef = useRef<HTMLImageElement>(null);
  const tryOnMaskImgRef = useRef<HTMLImageElement>(null);
  const tryOnCanvasRef = useRef<HTMLCanvasElement>(null);
  const [processedTryOnUrl, setProcessedTryOnUrl] = useState<string | null>(null);

  // Designer Workspace Refs
  const designerImgRef = useRef<HTMLImageElement>(null);
  const maskImgRef = useRef<HTMLImageElement>(null);
  const previewCanvasRef = useRef<HTMLCanvasElement>(null);

  const runTryOnIsolation = (): string | null => {
    if (removeTryOnBg && fittedImage && tryOnImgRef.current && tryOnCanvasRef.current) {
        const canvas = tryOnCanvasRef.current;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        const img = tryOnImgRef.current;
        if (!img.complete || img.naturalWidth === 0) return null;

        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        ctx?.clearRect(0, 0, canvas.width, canvas.height);

        let finalUrl: string | null = null;

        // AI MASKING BRANCH
        if (tryOnAiMaskActive && tryOnMask && tryOnMaskImgRef.current) {
            const maskImg = tryOnMaskImgRef.current;
            if (maskImg.complete && maskImg.naturalWidth > 0) {
                const tempCanvas = document.createElement('canvas');
                tempCanvas.width = canvas.width;
                tempCanvas.height = canvas.height;
                const tempCtx = tempCanvas.getContext('2d');
                tempCtx?.drawImage(maskImg, 0, 0, canvas.width, canvas.height);
                
                let maskData = tempCtx?.getImageData(0, 0, canvas.width, canvas.height);
                
                if (matteErosion > 0 && maskData) {
                    const originalData = new Uint8ClampedArray(maskData.data);
                    const width = canvas.width;
                    const height = canvas.height;
                    const eroded = maskData.data;
                    const radius = matteErosion;

                    for (let y = radius; y < height - radius; y++) {
                        for (let x = radius; x < width - radius; x++) {
                            const idx = (y * width + x) * 4;
                            let minLuminance = 255;
                            for (let dy = -radius; dy <= radius; dy++) {
                                for (let dx = -radius; dx <= radius; dx++) {
                                    const nIdx = ((y + dy) * width + (x + dx)) * 4;
                                    const lum = (originalData[nIdx] + originalData[nIdx+1] + originalData[nIdx+2]) / 3;
                                    if (lum < minLuminance) minLuminance = lum;
                                    if (minLuminance === 0) break;
                                }
                                if (minLuminance === 0) break;
                            }
                            eroded[idx] = eroded[idx+1] = eroded[idx+2] = minLuminance;
                        }
                    }
                    tempCtx?.putImageData(maskData, 0, 0);
                }

                // APPLY MASK SOFTENING (Blur the mask itself for smooth edges)
                if (tryOnMaskSoftening > 0 && tempCtx) {
                    const blurCanvas = document.createElement('canvas');
                    blurCanvas.width = canvas.width;
                    blurCanvas.height = canvas.height;
                    const blurCtx = blurCanvas.getContext('2d');
                    if (blurCtx) {
                        blurCtx.filter = `blur(${tryOnMaskSoftening}px)`;
                        blurCtx.drawImage(tempCanvas, 0, 0);
                        // Update maskData to blurred version
                        maskData = blurCtx.getImageData(0, 0, canvas.width, canvas.height);
                    }
                }

                // 3. Composite original image with (eroded/softened) mask
                ctx?.drawImage(img, 0, 0);
                const imgData = ctx?.getImageData(0, 0, canvas.width, canvas.height);
                const finalMaskData = maskData || tempCtx?.getImageData(0, 0, canvas.width, canvas.height);

                if (imgData && finalMaskData) {
                    const data = imgData.data;
                    const mask = finalMaskData.data;

                    for (let i = 0; i < data.length; i += 4) {
                        const maskLum = (mask[i] + mask[i+1] + mask[i+2]) / 3;
                        data[i+3] = tryOnInvertBg ? (255 - maskLum) : maskLum;

                        if (tryOnSpillSuppression > 0 && data[i+3] > 0) {
                            const r = data[i]; const g = data[i+1]; const b = data[i+2];
                            const avgRB = (r + b) / 2;
                            if (g > avgRB) {
                                const factor = tryOnSpillSuppression / 100;
                                data[i+1] = g * (1 - factor) + avgRB * factor;
                            }
                        }
                    }

                    ctx?.putImageData(imgData, 0, 0);
                    setProcessedTryOnUrl(canvas.toDataURL('image/png'));
                    return canvas.toDataURL('image/png');
                }
            }
        }

        // FALLBACK: Color Keying
        ctx?.drawImage(img, 0, 0);
        const imageData = ctx?.getImageData(0, 0, canvas.width, canvas.height);
        if (imageData) {
            const data = imageData.data;
            const key = { r: data[0], g: data[1], b: data[2] };
            for(let i = 0; i < data.length; i += 4) { 
                const r = data[i]; const g = data[i+1]; const b = data[i+2];
                const isMatch = Math.abs(r - key.r) < tryOnTolerance && Math.abs(g - key.g) < tryOnTolerance && Math.abs(b - key.b) < tryOnTolerance;
                
                if (tryOnInvertBg) { if (!isMatch) data[i+3] = 0; } 
                else { if (isMatch) data[i+3] = 0; }

                if (tryOnSpillSuppression > 0 && data[i+3] > 0) {
                    const rP = data[i]; const gP = data[i+1]; const bP = data[i+2];
                    const avgRB = (rP + bP) / 2;
                    if (gP > avgRB) {
                        const factor = tryOnSpillSuppression / 100;
                        data[i+1] = gP * (1 - factor) + avgRB * factor;
                    }
                }
            }
            ctx?.putImageData(imageData, 0, 0);
            finalUrl = canvas.toDataURL('image/png');
            setProcessedTryOnUrl(finalUrl);
            return finalUrl;
        }
    } else {
        setProcessedTryOnUrl(null);
    }
    return null;
  };

  useEffect(() => {
    runTryOnIsolation();
  }, [removeTryOnBg, tryOnTolerance, matteErosion, fittedImage, tryOnMask, tryOnAiMaskActive, tryOnSpillSuppression, tryOnMaskSoftening, tryOnInvertBg]);



  useEffect(() => {
    scanWardrobe();
  }, [state.saveDirectoryHandle]);

  const scanWardrobe = async () => {
    if (!state.saveDirectoryHandle) return;
    try {
      const wardrobeHandle = await state.saveDirectoryHandle.getDirectoryHandle('wardrobe', { create: true });
      const items: WardrobeItem[] = [];
      for await (const entry of (wardrobeHandle as any).values()) {
        if (entry.kind === 'file' && entry.name.endsWith('.png')) {
          // In a real app, we might store metadata in a separate JSON or use file naming
          // For now, we'll just load the files as entries
          const file = await entry.getFile();
          const reader = new FileReader();
          const dataUrl = await new Promise<string>((resolve) => {
            reader.onload = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });
          
          items.push({
            id: entry.name,
            url: dataUrl,
            name: entry.name.replace('.png', '').split('-').slice(1).join(' '),
            prompt: "Saved costume asset",
            category: "General",
            timestamp: file.lastModified
          });
        }
      }
      dispatch({ type: 'SET_WARDROBE_ITEMS', payload: items.sort((a,b) => b.timestamp - a.timestamp) });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: `Wardrobe scan failed: ${e.message}`, type: 'error' } });
    }
  };

  const saveToWardrobe = async (imageUrl: string, prompt: string) => {
    if (!state.saveDirectoryHandle) return;
    try {
      const wardrobeHandle = await state.saveDirectoryHandle.getDirectoryHandle('wardrobe', { create: true });
      const filename = `WARDROBE-${Date.now()}.png`;
      const fileHandle = await wardrobeHandle.getFileHandle(filename, { create: true });
      const writable = await fileHandle.createWritable();
      const res = await fetch(imageUrl);
      const blob = await res.blob();
      await writable.write(blob);
      await writable.close();
      
      const newItem: WardrobeItem = {
        id: filename,
        url: imageUrl,
        name: prompt.substring(0, 20),
        prompt: prompt,
        category: "Designer",
        timestamp: Date.now()
      };
      
      dispatch({ type: 'ADD_WARDROBE_ITEM', payload: newItem });
      dispatch({ type: 'ADD_LOG', payload: { message: `Costume saved to wardrobe: ${filename}`, type: 'success' } });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: `Failed to save wardrobe item: ${e.message}`, type: 'error' } });
    }
  };

  const handleDesignerGenerate = async () => {
    if (!designerPrompt || !state.apiKey) return;
    setDesignerMask(null);
    dispatch({ type: 'SET_PROCESSING', payload: true });
    try {
      const res = await GeminiService.generateImage(
        `Professional standalone apparel photography: ${designerPrompt}. 
         Film quality, detailed fabric texture, cinematic studio lighting, solid white studio background. 
         Isolated garment, no background distractions. Strictly solid white background only.`,
        state.apiKey,
        state.model,
        [],
        { aspectRatio: '1:1' }
      );
      setDesignerImage(res);
      dispatch({ type: 'ADD_LOG', payload: { message: "Costume generated on studio white.", type: 'success' } });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: e.message, type: 'error' } });
    } finally {
      dispatch({ type: 'SET_PROCESSING', payload: false });
    }
  };

  const handleUploadCostume = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const dataUrl = reader.result as string;
      setDesignerImage(dataUrl);
      setDesignerPrompt(file.name.replace(/\.[^/.]+$/, "")); // Use filename as default prompt
      setActiveTab('designer'); // Switch to designer to show the preview
      dispatch({ type: 'ADD_LOG', payload: { message: `Loaded: ${file.name}. Click 'Save' to add to library.`, type: 'info' } });
    };
    reader.readAsDataURL(file);
  };

  const handleTryOn = async () => {
    if (!selectedCharacter || !selectedCostume || !state.apiKey) return;
    setRemoveTryOnBg(false);
    setTryOnMask(null);
    dispatch({ type: 'SET_PROCESSING', payload: true });
    try {
      // PASS 1: Generate Fusion on Neon Green for best edge isolation
      const res = await GeminiService.generateImage(
        `Perform a professional virtual try-on and fashion fitting. 
         [IMAGE 1] is the target SUBJECT. 
         [IMAGE 2] is the standalone COSTUME to fit.
         
         OBJECTIVE: Apply the costume from [IMAGE 2] onto the subject in [IMAGE 1].
         CRITICAL CONSTRAINTS:
         1. MAINTAIN the subject's exact facial identity, hairstyle, and body proportions from [IMAGE 1].
         2. FULLY REPLACE their current clothing with the outfit in [IMAGE 2].
         3. Adjust the fit to match their pose and lighting naturally.
         4. ${tryOnNote || "Clean studio execution."}
         5. Use a solid Neon Green background (#39FF14) for perfect subject isolation.`,
        state.apiKey,
        state.model,
        [
          { url: selectedCharacter.url, label: "Subject Reference" },
          { url: selectedCostume.url, label: "Costume Reference" }
        ],
        { aspectRatio: '1:1' }
      );
      setFittedImage(res);
      dispatch({ type: 'ADD_LOG', payload: { message: "Fusion complete. Creating character edge mask...", type: 'info' } });

      // PASS 2: Generate Fusion Mask
      try {
        const maskRes = await GeminiService.generateImage(
            `DIGITAL CHARACTER SEGMENTATION MASK: Create a pure black and white silhouette of the character in [IMAGE 1].
             The entire character silhouette (skin, hair, clothes) MUST be PURE WHITE (#FFFFFF).
             The background MUST be PURE BLACK (#000000).
             Film-grade precision, no gradients, no shadows.`,
            state.apiKey,
            state.model,
            [{ url: res, label: "Reference" }],
            { aspectRatio: '1:1' }
        );
        setTryOnMask(maskRes);
        dispatch({ type: 'ADD_LOG', payload: { message: "Character mask generated with high fidelity", type: 'success' } });
      } catch (maskErr: any) {
        dispatch({ type: 'ADD_LOG', payload: { message: `Character mask failed: ${maskErr.message}. Falling back to standard keying.`, type: 'error' } });
      }

    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: e.message, type: 'error' } });
    } finally {
      dispatch({ type: 'SET_PROCESSING', payload: false });
    }
  };

  const handleAddToCast = () => {
    const freshUrl = runTryOnIsolation();
    const finalUrl = freshUrl || processedTryOnUrl || fittedImage;
    if (!finalUrl || !selectedCharacter) return;
    const newMember: CastMember = {
      id: `fitted-${Date.now()}`,
      url: finalUrl,
      tag: 'front',
      name: `${selectedCharacter.name} (Fitted)`,
      profile: {
        identity: selectedCharacter.profile?.identity || selectedCharacter.name,
        wardrobe: selectedCostume?.prompt || "Selected Wardrobe",
        accessories: selectedCharacter.profile?.accessories || "",
        style: selectedCharacter.profile?.style || ""
      }
    };
    dispatch({ type: 'ADD_CAST', payload: newMember });
    dispatch({ type: 'ADD_LOG', payload: { message: "Character added to cast library", type: 'success' } });
  };

  const handleSaveFittedToActors = async () => {
    const freshUrl = runTryOnIsolation();
    const finalUrl = freshUrl || processedTryOnUrl || fittedImage;
    if (!finalUrl || !state.saveDirectoryHandle) {
        if (!state.saveDirectoryHandle) dispatch({ type: 'ADD_LOG', payload: { message: "No save directory configured", type: 'error' } });
        return;
    }

    try {
        const actorsDir = await state.saveDirectoryHandle.getDirectoryHandle('Actors', { create: true });
        const safeName = (selectedCharacter?.name || 'FittedActor').slice(0, 30).replace(/[^a-z0-9]/gi, '_');
        const filename = `Actor-Fitted-${Date.now()}-${safeName}.png`;
        const fileHandle = await actorsDir.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        const res = await fetch(finalUrl);
        const blob = await res.blob();
        await writable.write(blob);
        await writable.close();

        // Also add to global actor library state if it exists
        const newActor: CastMember = {
            id: `actor-fitted-${Date.now()}`,
            url: finalUrl,
            tag: 'front',
            name: `${selectedCharacter?.name} (Fitted)`,
            profile: {
                identity: selectedCharacter?.profile?.identity || "Unknown",
                wardrobe: selectedCostume?.name || "Fitted Costume",
                accessories: "",
                style: "Virtual Try-On"
            }
        };
        dispatch({ type: 'ADD_ACTOR_LIBRARY', payload: newActor });
        dispatch({ type: 'ADD_LOG', payload: { message: `Saved to Actors Library: ${filename}`, type: 'success' } });

    } catch (e: any) {
        dispatch({ type: 'ADD_LOG', payload: { message: `Failed to save actor: ${e.message}`, type: 'error' } });
    }
  };

  const downloadImage = (url: string, filename: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="h-full bg-[#0f0f11] flex overflow-hidden">
      {/* LEFT: WARDROBE LIBRARY */}
      <div className="w-80 border-r border-gray-800 bg-[#18181b] flex flex-col shadow-xl">
        <div className="p-4 border-b border-gray-800 flex justify-between items-center">
          <h2 className="text-sm font-black text-white tracking-widest uppercase">Wardrobe Library</h2>
          <div className="flex gap-1.5">
            <label className="p-1.5 hover:bg-gray-700 rounded transition-colors text-gray-400 cursor-pointer" title="Upload Costume">
              <Upload className="w-3.5 h-3.5" />
              <input type="file" className="hidden" accept="image/*" onChange={handleUploadCostume} />
            </label>
            <button onClick={scanWardrobe} className="p-1.5 hover:bg-gray-700 rounded transition-colors text-gray-400" title="Scan Folder">
              <RefreshCcw className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
        
        <div className="flex-grow overflow-y-auto p-4 space-y-4">
          {!state.saveDirectoryHandle && (
            <div className="p-4 bg-yellow-500/5 border border-yellow-500/20 rounded-lg">
                <p className="text-[10px] text-yellow-500 font-bold leading-relaxed">
                    ⚠️ PLEASE SELECT A SAVE FOLDER IN SETTINGS TO ENABLE LOCAL WARDROBE STORAGE.
                </p>
            </div>
          )}
          
          <div className="grid grid-cols-2 gap-2">
            {state.wardrobeItems.map(item => (
              <button 
                key={item.id}
                onClick={() => setSelectedCostume(item)}
                className={`aspect-square rounded-lg border overflow-hidden transition-all group relative ${selectedCostume?.id === item.id ? 'border-yellow-500 border-2 shadow-lg shadow-yellow-500/20' : 'border-gray-800 hover:border-gray-600'}`}
              >
                <img src={item.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                    <button 
                        onClick={(e) => { e.stopPropagation(); dispatch({ type: 'SET_INSPECT_IMAGE', payload: item.url }); }}
                        className="bg-blue-500/80 hover:bg-blue-500 text-white p-1.5 rounded-full shadow-lg"
                        title="Inspect Large"
                    >
                        <Maximize className="w-3.5 h-3.5" />
                    </button>
                    <span className="text-[8px] font-bold text-white uppercase truncate absolute bottom-2 left-2 right-2 text-center">{item.name}</span>
                </div>
              </button>
            ))}
          </div>
          
          {state.wardrobeItems.length === 0 && (
            <div className="flex flex-col items-center justify-center py-10 opacity-30">
               <Shirt className="w-10 h-10 mb-2" />
               <span className="text-[10px] uppercase font-bold tracking-tighter">Library Empty</span>
            </div>
          )}
        </div>
      </div>

      {/* CENTER: WORKSPACE */}
      <div className="flex-grow flex flex-col bg-[#09090b]">
        {/* TABS */}
        <div className="flex bg-[#18181b] px-4 pt-4 gap-4 border-b border-gray-800">
          <button 
            onClick={() => setActiveTab('designer')}
            className={`pb-3 px-4 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'designer' ? 'border-yellow-500 text-yellow-500' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
          >
            Costume Designer
          </button>
          <button 
            onClick={() => setActiveTab('library')}
            className={`pb-3 px-4 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'library' ? 'border-yellow-500 text-yellow-500' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
          >
            Virtual Try-On Room
          </button>
        </div>

        <div className="flex-grow overflow-y-auto p-8">
          {activeTab === 'designer' ? (
            <div className="max-w-4xl mx-auto grid grid-cols-2 gap-8">
                <div className="space-y-6">
                    <div className="bg-[#18181b] p-6 rounded-2xl border border-gray-800 shadow-xl">
                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest flex items-center gap-2">
                            <Sparkles className="w-4 h-4 text-yellow-500" /> Designer Workshop
                        </h3>
                        <textarea 
                            className="w-full bg-[#09090b] border border-[#27272a] p-4 rounded-xl text-sm text-gray-200 focus:border-yellow-500 focus:outline-none transition-colors h-40 resize-none mb-4"
                            placeholder="Describe the clothing (e.g. 'A futuristic chrome-plated flight suit with neon orange cabling')..."
                            value={designerPrompt}
                            onChange={(e) => setDesignerPrompt(e.target.value)}
                        />
                        <button 
                          onClick={handleDesignerGenerate}
                          disabled={state.isProcessing || !designerPrompt}
                          className="w-full bg-gradient-to-r from-yellow-500 to-yellow-600 hover:from-yellow-400 hover:to-yellow-500 text-black py-3 rounded-xl font-black text-xs uppercase tracking-[0.2em] shadow-lg shadow-yellow-500/20 transition-all active:scale-95 disabled:opacity-50"
                        >
                          Generate Costume
                        </button>
                    </div>
                </div>

                <div className="aspect-square bg-black rounded-2xl border border-gray-800 shadow-2xl flex items-center justify-center overflow-hidden relative group bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                    {designerImage && (
                        <img 
                            ref={designerImgRef} 
                            src={designerImage} 
                            className="hidden" 
                        />
                    )}

                    {designerMask && (
                        <img 
                            ref={maskImgRef} 
                            src={designerMask} 
                            className="hidden" 
                        />
                    )}
                    
                    {designerImage ? (
                        <div className="relative w-full h-full">
                            <img src={designerImage} className="w-full h-full object-contain" />
                            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-3 z-50">
                                <button 
                                    onClick={() => saveToWardrobe(designerImage!, designerPrompt)}
                                    className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-3 rounded-full font-black text-[10px] uppercase tracking-widest shadow-2xl shadow-blue-900/40 border border-blue-400 transition-all active:scale-95 flex items-center gap-3"
                                >
                                    <Shirt className="w-4 h-4" /> Save to Wardrobe
                                </button>
                                <button 
                                    onClick={() => downloadImage(designerImage!, `costume-${Date.now()}.png`)}
                                    className="bg-white/10 hover:bg-white/20 text-white p-3 rounded-full transition-all border border-white/10 active:scale-95"
                                    title="Download Asset"
                                >
                                    <Download className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col items-center opacity-20">
                            <Shirt className="w-16 h-16 mb-4" />
                            <span className="text-xs font-black uppercase tracking-widest">Awaiting Creation</span>
                        </div>
                    )}

                    <canvas ref={previewCanvasRef} className="hidden" />

                    <div className="absolute top-4 right-4 flex items-center gap-2">
                        <button 
                            onClick={(e) => { e.stopPropagation(); dispatch({ type: 'SET_INSPECT_IMAGE', payload: designerImage! }); }}
                            className="bg-black/60 hover:bg-black/80 text-white p-2 rounded-full border border-white/10 backdrop-blur-sm transition-all active:scale-95"
                            title="Inspect Large"
                        >
                            <Maximize className="w-4 h-4" />
                        </button>
                        <div className="bg-black/60 px-3 py-1.5 rounded-full border border-white/10 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] backdrop-blur-sm">
                            Designer Workshop
                        </div>
                    </div>
                </div>
            </div>
          ) : (
            <div className="max-w-6xl mx-auto grid grid-cols-12 gap-8">
                {/* SELECTOR COLUMN */}
                <div className="col-span-4 space-y-6">
                    <div className="bg-[#18181b] p-6 rounded-2xl border border-gray-800 shadow-xl">
                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest">1. Selected Subject</h3>
                        <div className="grid grid-cols-4 gap-2 mb-6 h-32 overflow-y-auto p-2">
                            {state.cast.map(c => (
                                <button 
                                    key={c.id} 
                                    onClick={() => setSelectedCharacter(c)}
                                    className={`aspect-square rounded border transition-all overflow-hidden ${selectedCharacter?.id === c.id ? 'border-green-500 ring-1 ring-green-500' : 'border-gray-800 hover:border-gray-600'}`}
                                >
                                    <img src={c.url} className="w-full h-full object-cover" />
                                </button>
                            ))}
                            {state.cast.length === 0 && (
                                <div className="col-span-4 py-8 text-center text-[10px] text-gray-600 uppercase font-bold">No Cast Members Available</div>
                            )}
                        </div>

                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest border-t border-gray-800 pt-6">2. Active Wardrobe</h3>
                        <div className="aspect-square bg-[#09090b] rounded-xl border border-gray-800 mb-6 flex items-center justify-center overflow-hidden">
                            {selectedCostume ? (
                                <img src={selectedCostume.url} className="w-full h-full object-contain" />
                            ) : (
                                <Shirt className="w-10 h-10 opacity-10" />
                            )}
                        </div>

                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest border-t border-gray-800 pt-6">3. Fitting Notes</h3>
                        <textarea 
                            className="w-full bg-[#09090b] border border-[#27272a] p-3 rounded-lg text-xs text-gray-300 h-20 resize-none mb-4 focus:border-yellow-500 focus:outline-none"
                            placeholder="Optional: adjust the fit (e.g. 'heavy battle damage')..."
                            value={tryOnNote}
                            onChange={(e) => setTryOnNote(e.target.value)}
                        />

                        <button 
                            onClick={handleTryOn}
                            disabled={state.isProcessing || !selectedCharacter || !selectedCostume}
                            className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl shadow-blue-500/20 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            Execute Virtual Try-On
                        </button>
                    </div>
                </div>

                {/* RESULT COLUMN */}
                <div className="col-span-8">
                    <div className="aspect-square bg-black rounded-3xl border border-gray-800 shadow-2xl flex items-center justify-center overflow-hidden relative group border-4 border-[#18181b]">
                        {fittedImage ? (
                            <>
                                <img 
                                    ref={tryOnImgRef} 
                                    src={fittedImage} 
                                    className={processedTryOnUrl ? 'hidden' : 'w-full h-full object-cover'} 
                                />
                                {processedTryOnUrl && (
                                    <img src={processedTryOnUrl} className="w-full h-full object-cover" />
                                )}
                                <canvas ref={tryOnCanvasRef} className="hidden" />
                                {tryOnMask && (
                                    <img ref={tryOnMaskImgRef} src={tryOnMask} className="hidden" />
                                )}
                            </>
                        ) : (
                            <div className="flex flex-col items-center opacity-10">
                                <UserPlus className="w-24 h-24 mb-6" />
                                <span className="text-sm font-black uppercase tracking-[0.5em]">Ready for Fitting</span>
                            </div>
                        )}
                        
                        <div className="absolute top-6 left-6 flex items-center gap-2 z-20">
                             <div className="bg-blue-600 text-[10px] font-black uppercase px-3 py-1 rounded-full text-white shadow-lg">FITTING MIRROR</div>
                             <div className="bg-black/40 backdrop-blur-md text-[9px] font-bold text-gray-300 px-3 py-1 rounded-full border border-white/10 uppercase tracking-widest">
                                {selectedCharacter ? selectedCharacter.name : 'No Subject'} + {selectedCostume ? selectedCostume.name : 'No Costume'}
                             </div>
                        </div>

                        {fittedImage && (
                            <div className="absolute top-6 right-6 flex flex-col gap-3 z-20 bg-black/60 p-4 rounded-3xl border border-white/10 backdrop-blur-md shadow-2xl">
                                <div className="flex items-center justify-between gap-6">
                                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            checked={removeTryOnBg} 
                                            onChange={(e) => setRemoveTryOnBg(e.target.checked)} 
                                            className="w-4 h-4 accent-blue-500 rounded" 
                                        />
                                        <Eraser className="w-3.5 h-3.5" /> Remove BG
                                    </label>

                                    {tryOnMask && (
                                        <label className="text-[9px] font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 cursor-pointer">
                                            <input 
                                                type="checkbox" 
                                                checked={tryOnAiMaskActive} 
                                                onChange={(e) => setTryOnAiMaskActive(e.target.checked)} 
                                                className="w-3.5 h-3.5 accent-blue-500 rounded" 
                                            />
                                            <Sparkles className="w-3 h-3" /> AI Masking
                                        </label>
                                    )}
                                </div>
                                
                                {removeTryOnBg && (
                                    <div className="space-y-3 pt-2 border-t border-white/5">
                                        <div className="flex items-center justify-between text-[9px] font-bold text-gray-500 uppercase tracking-wider">
                                            <span>Tolerance</span>
                                            <span>{tryOnTolerance}%</span>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="1" max="100" 
                                            value={tryOnTolerance} 
                                            onChange={(e) => setTryOnTolerance(parseInt(e.target.value))}
                                            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                                        />

                                        {tryOnMask && tryOnAiMaskActive && (
                                            <>
                                                <div className="flex items-center justify-between text-[9px] font-bold text-blue-400/60 uppercase tracking-wider pt-1">
                                                    <span>Matte Contraction</span>
                                                    <span>{matteErosion}px</span>
                                                </div>
                                                <input 
                                                    type="range" 
                                                    min="0" max="10" 
                                                    step="1"
                                                    value={matteErosion} 
                                                    onChange={(e) => setMatteErosion(parseInt(e.target.value))}
                                                    className="w-full h-1 bg-blue-900/30 rounded-lg appearance-none cursor-pointer"
                                                />

                                                <div className="flex items-center justify-between text-[9px] font-bold text-blue-400/60 uppercase tracking-wider pt-1">
                                                    <span>Mask Softening</span>
                                                    <span>{tryOnMaskSoftening}px</span>
                                                </div>
                                                <input 
                                                    type="range" 
                                                    min="0" max="10" 
                                                    step="0.5"
                                                    value={tryOnMaskSoftening} 
                                                    onChange={(e) => setTryOnMaskSoftening(parseFloat(e.target.value))}
                                                    className="w-full h-1 bg-blue-900/30 rounded-lg appearance-none cursor-pointer"
                                                />
                                            </>
                                        )}

                                        <div className="flex items-center justify-between text-[9px] font-bold text-green-400/60 uppercase tracking-wider pt-1">
                                            <span>Spill Suppression</span>
                                            <span>{tryOnSpillSuppression}%</span>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="0" max="100" 
                                            value={tryOnSpillSuppression} 
                                            onChange={(e) => setTryOnSpillSuppression(parseInt(e.target.value))}
                                            className="w-full h-1 bg-green-900/30 rounded-lg appearance-none cursor-pointer"
                                        />
                                        <div className="flex items-center justify-between pt-2 border-t border-white/5 mt-2">
                                            <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2 cursor-pointer hover:text-gray-300 transition-colors pt-2">
                                                <input 
                                                    type="checkbox" 
                                                    checked={tryOnInvertBg} 
                                                    onChange={(e) => setTryOnInvertBg(e.target.checked)} 
                                                    className="w-3.5 h-3.5 accent-red-500 rounded border-gray-700 bg-black/50"
                                                />
                                                Invert Matte
                                            </label>
                                            <div className="w-10 h-10 bg-black/60 border border-white/5 rounded-xl overflow-hidden shadow-inner flex items-center justify-center mt-2">
                                                <canvas ref={tryOnCanvasRef} className="max-w-full max-h-full object-contain scale-150" />
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {fittedImage && (
                            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-4 z-30 bg-black/40 backdrop-blur-2xl border border-white/10 p-2 rounded-2xl shadow-2xl animate-in slide-in-from-bottom-8 duration-500">
                                <button 
                                    onClick={handleAddToCast}
                                    className="w-14 h-14 bg-emerald-500/20 hover:bg-emerald-500 text-emerald-500 hover:text-white rounded-xl transition-all transform hover:scale-110 flex items-center justify-center border border-emerald-500/30 shadow-[0_0_15px_rgba(16,185,129,0.2)]"
                                    title="Add to Cast Library"
                                >
                                    <UserPlus className="w-6 h-6 stroke-[2.5]" />
                                </button>
                                <button 
                                    onClick={() => downloadImage(processedTryOnUrl || fittedImage!, `fitted-${selectedCharacter?.name || 'character'}.png`)}
                                    className="w-14 h-14 bg-white/10 hover:bg-white text-white hover:text-black rounded-xl transition-all transform hover:scale-110 flex items-center justify-center border border-white/20 shadow-[0_0_15px_rgba(255,255,255,0.1)]"
                                    title="Download Transparent PNG"
                                >
                                    <Download className="w-6 h-6 stroke-[2.5]" />
                                </button>
                                <button 
                                    onClick={() => setFittedImage(null)}
                                    className="w-14 h-14 bg-red-500/20 hover:bg-red-500 text-red-500 hover:text-white rounded-xl transition-all transform hover:scale-110 flex items-center justify-center border border-red-500/30 shadow-[0_0_15px_rgba(239,68,68,0.2)]"
                                    title="Discard Result"
                                >
                                    <X className="w-6 h-6 stroke-[3]" />
                                </button>
                                <button 
                                    onClick={handleSaveFittedToActors}
                                    className="w-14 h-14 bg-indigo-500/20 hover:bg-indigo-500 text-indigo-500 hover:text-white rounded-xl transition-all transform hover:scale-110 flex items-center justify-center border border-indigo-500/30 shadow-[0_0_15px_rgba(99,102,241,0.2)]"
                                    title="Save to Global Actor Library (Disk)"
                                >
                                    <Save className="w-6 h-6 stroke-[2.5]" />
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// C. Prop & Accessory Studio Component
const PropAccessoryStudio = () => {
  const { state, dispatch } = useContext(AppContext);
  const [activeTab, setActiveTab] = useState<'designer' | 'library'>('designer');
  const [designerPrompt, setDesignerPrompt] = useState("");
  const [designerImage, setDesignerImage] = useState<string | null>(null);
  const [selectedProp, setSelectedProp] = useState<PropItem | null>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<CastMember | null>(null);
  const [appliedImage, setAppliedImage] = useState<string | null>(null);
  const [applyNote, setApplyNote] = useState("");
  const [applyMask, setApplyMask] = useState<string | null>(null);

  // Apply Removal State
  const [removeApplyBg, setRemoveApplyBg] = useState(false);
  const [applyAiMaskActive, setApplyAiMaskActive] = useState(true);
  const [applyTolerance, setApplyTolerance] = useState(15);
  const [applySpillSuppression, setApplySpillSuppression] = useState(100); 
  const [applyMaskSoftening, setApplyMaskSoftening] = useState(1.5);
  const [applyInvertBg, setApplyInvertBg] = useState(false);
  const [matteErosion, setMatteErosion] = useState(1);
  const applyImgRef = useRef<HTMLImageElement>(null);
  const applyMaskImgRef = useRef<HTMLImageElement>(null);
  const applyCanvasRef = useRef<HTMLCanvasElement>(null);
  const [processedApplyUrl, setProcessedApplyUrl] = useState<string | null>(null);

  const runApplyIsolation = (): string | null => {
    if (removeApplyBg && appliedImage && applyImgRef.current && applyCanvasRef.current) {
        const canvas = applyCanvasRef.current;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        const img = applyImgRef.current;
        if (!img.complete || img.naturalWidth === 0) return null;

        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        ctx?.clearRect(0, 0, canvas.width, canvas.height);

        // AI MASKING BRANCH
        if (applyAiMaskActive && applyMask && applyMaskImgRef.current) {
            const maskImg = applyMaskImgRef.current;
            if (maskImg.complete && maskImg.naturalWidth > 0) {
                const tempCanvas = document.createElement('canvas');
                tempCanvas.width = canvas.width;
                tempCanvas.height = canvas.height;
                const tempCtx = tempCanvas.getContext('2d');
                tempCtx?.drawImage(maskImg, 0, 0, canvas.width, canvas.height);
                
                let maskData = tempCtx?.getImageData(0, 0, canvas.width, canvas.height);
                
                if (matteErosion > 0 && maskData) {
                    const originalData = new Uint8ClampedArray(maskData.data);
                    const width = canvas.width;
                    const height = canvas.height;
                    const eroded = maskData.data;
                    const radius = matteErosion;

                    for (let y = radius; y < height - radius; y++) {
                        for (let x = radius; x < width - radius; x++) {
                            const idx = (y * width + x) * 4;
                            let minLuminance = 255;
                            for (let dy = -radius; dy <= radius; dy++) {
                                for (let dx = -radius; dx <= radius; dx++) {
                                    const nIdx = ((y + dy) * width + (x + dx)) * 4;
                                    const lum = (originalData[nIdx] + originalData[nIdx+1] + originalData[nIdx+2]) / 3;
                                    if (lum < minLuminance) minLuminance = lum;
                                }
                            }
                            eroded[idx] = eroded[idx+1] = eroded[idx+2] = minLuminance;
                        }
                    }
                    tempCtx?.putImageData(maskData, 0, 0);
                }

                if (applyMaskSoftening > 0 && tempCtx) {
                    const blurCanvas = document.createElement('canvas');
                    blurCanvas.width = canvas.width;
                    blurCanvas.height = canvas.height;
                    const blurCtx = blurCanvas.getContext('2d');
                    if (blurCtx) {
                        blurCtx.filter = `blur(${applyMaskSoftening}px)`;
                        blurCtx.drawImage(tempCanvas, 0, 0);
                        maskData = blurCtx.getImageData(0, 0, canvas.width, canvas.height);
                    }
                }

                ctx?.drawImage(img, 0, 0);
                const imgData = ctx?.getImageData(0, 0, canvas.width, canvas.height);
                if (imgData && maskData) {
                    const data = imgData.data;
                    const mask = maskData.data;
                    for (let i = 0; i < data.length; i += 4) {
                        const maskLum = (mask[i] + mask[i+1] + mask[i+2]) / 3;
                        data[i+3] = applyInvertBg ? (255 - maskLum) : maskLum;
                        if (applySpillSuppression > 0 && data[i+3] > 0) {
                            const r = data[i]; const g = data[i+1]; const b = data[i+2];
                            const avgRB = (r + b) / 2;
                            if (g > avgRB) {
                                const factor = applySpillSuppression / 100;
                                data[i+1] = g * (1 - factor) + avgRB * factor;
                            }
                        }
                    }
                    ctx?.putImageData(imgData, 0, 0);
                    const url = canvas.toDataURL('image/png');
                    setProcessedApplyUrl(url);
                    return url;
                }
            }
        }

        // FALLBACK: Color Keying
        ctx?.drawImage(img, 0, 0);
        const imageData = ctx?.getImageData(0, 0, canvas.width, canvas.height);
        if (imageData) {
            const data = imageData.data;
            const key = { r: data[0], g: data[1], b: data[2] };
            for(let i = 0; i < data.length; i += 4) { 
                const r = data[i]; const g = data[i+1]; const b = data[i+2];
                const isMatch = Math.abs(r - key.r) < applyTolerance && Math.abs(g - key.g) < applyTolerance && Math.abs(b - key.b) < applyTolerance;
                if (applyInvertBg) { if (!isMatch) data[i+3] = 0; } 
                else { if (isMatch) data[i+3] = 0; }
                if (applySpillSuppression > 0 && data[i+3] > 0) {
                    const rP = data[i]; const gP = data[i+1]; const bP = data[i+2];
                    const avgRB = (rP + bP) / 2;
                    if (gP > avgRB) {
                        const factor = applySpillSuppression / 100;
                        data[i+1] = gP * (1 - factor) + avgRB * factor;
                    }
                }
            }
            ctx?.putImageData(imageData, 0, 0);
            const url = canvas.toDataURL('image/png');
            setProcessedApplyUrl(url);
            return url;
        }
    } else {
        setProcessedApplyUrl(null);
    }
    return null;
  };

  useEffect(() => {
    runApplyIsolation();
  }, [removeApplyBg, applyTolerance, matteErosion, appliedImage, applyMask, applyAiMaskActive, applySpillSuppression, applyMaskSoftening, applyInvertBg]);

  useEffect(() => {
    scanProps();
  }, [state.saveDirectoryHandle]);

  const scanProps = async () => {
    if (!state.saveDirectoryHandle) return;
    try {
      const propsHandle = await state.saveDirectoryHandle.getDirectoryHandle('props', { create: true });
      const items: PropItem[] = [];
      for await (const entry of (propsHandle as any).values()) {
        if (entry.kind === 'file' && entry.name.endsWith('.png')) {
          const file = await entry.getFile();
          const reader = new FileReader();
          const dataUrl = await new Promise<string>((resolve) => {
            reader.onload = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });
          items.push({
            id: entry.name,
            url: dataUrl,
            name: entry.name.replace('.png', '').split('-').slice(1).join(' '),
            prompt: "Saved prop asset",
            category: "General",
            timestamp: file.lastModified
          });
        }
      }
      dispatch({ type: 'SET_PROP_ITEMS', payload: items.sort((a,b) => b.timestamp - a.timestamp) });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: `Prop scan failed: ${e.message}`, type: 'error' } });
    }
  };

  const saveToProps = async (imageUrl: string, prompt: string) => {
    if (!state.saveDirectoryHandle) {
      dispatch({ type: 'ADD_LOG', payload: { message: "Cannot save: No save directory selected in settings.", type: 'error' } });
      return;
    }
    try {
      const propsHandle = await state.saveDirectoryHandle.getDirectoryHandle('props', { create: true });
      const filename = `PROP-${Date.now()}.png`;
      const fileHandle = await propsHandle.getFileHandle(filename, { create: true });
      const writable = await fileHandle.createWritable();
      const res = await fetch(imageUrl);
      const blob = await res.blob();
      await writable.write(blob);
      await writable.close();
      const newItem: PropItem = {
        id: filename,
        url: imageUrl,
        name: prompt.substring(0, 20),
        prompt: prompt,
        category: "Designer",
        timestamp: Date.now()
      };
      dispatch({ type: 'ADD_PROP_ITEM', payload: newItem });
      dispatch({ type: 'ADD_LOG', payload: { message: `Prop saved to library: ${filename}`, type: 'success' } });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: `Failed to save prop: ${e.message}`, type: 'error' } });
    }
  };

  const handleDesignerGenerate = async () => {
    if (!designerPrompt || !state.apiKey) return;
    dispatch({ type: 'SET_PROCESSING', payload: true });
    try {
      const res = await GeminiService.generateImage(
        `Professional standalone prop and accessory photography: ${designerPrompt}. 
         High fidelity, cinematic studio lighting, solid white studio background. 
         Isolated object, no background distractions. Strictly solid white background only.`,
        state.apiKey,
        state.model,
        [],
        { aspectRatio: '1:1' }
      );
      setDesignerImage(res);
      dispatch({ type: 'ADD_LOG', payload: { message: "Prop generated on studio white.", type: 'success' } });
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: e.message, type: 'error' } });
    } finally {
      dispatch({ type: 'SET_PROCESSING', payload: false });
    }
  };

  const handleUploadProp = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      setDesignerImage(reader.result as string);
      setDesignerPrompt(file.name.replace(/\.[^/.]+$/, ""));
      setActiveTab('designer');
    };
    reader.readAsDataURL(file);
  };

  const handleApply = async () => {
    if (!selectedCharacter || !selectedProp || !state.apiKey) return;
    setRemoveApplyBg(false);
    setApplyMask(null);
    dispatch({ type: 'SET_PROCESSING', payload: true });
    try {
      const res = await GeminiService.generateImage(
        `Perform a professional character prop integration. 
         [IMAGE 1] is the target SUBJECT. 
         [IMAGE 2] is the standalone PROP/ACCESSORY to integrate.
         
         OBJECTIVE: Accurately place and integrate the prop from [IMAGE 2] onto/with the subject in [IMAGE 1] according to these placement notes: ${applyNote || "Natural integration"}.
         CRITICAL CONSTRAINTS:
         1. MAINTAIN the subject's exact facial identity and proportions.
         2. INTEGRATE the prop naturally (held, worn, or placed nearby).
         3. Adjust lighting and shadows to match.
         4. Use a solid Neon Green background (#39FF14) for isolation.`,
        state.apiKey,
        state.model,
        [
          { url: selectedCharacter.url, label: "Subject Reference" },
          { url: selectedProp.url, label: "Prop Reference" }
        ],
        { aspectRatio: '1:1' }
      );
      setAppliedImage(res);
      dispatch({ type: 'ADD_LOG', payload: { message: "Integration complete. Creating mask...", type: 'info' } });

      try {
        const maskRes = await GeminiService.generateImage(
            `PURE BLACK AND WHITE SILHOUETTE MASK: Subject + Integrated Prop = WHITE. Background = BLACK.`,
            state.apiKey,
            state.model,
            [{ url: res, label: "Reference" }],
            { aspectRatio: '1:1' }
        );
        setApplyMask(maskRes);
      } catch (maskErr: any) {
        dispatch({ type: 'ADD_LOG', payload: { message: `Mask failed: ${maskErr.message}`, type: 'error' } });
      }
    } catch (e: any) {
      dispatch({ type: 'ADD_LOG', payload: { message: e.message, type: 'error' } });
    } finally {
      dispatch({ type: 'SET_PROCESSING', payload: false });
    }
  };

  const handleAddToCast = () => {
    const finalUrl = processedApplyUrl || appliedImage;
    if (!finalUrl || !selectedCharacter) return;
    const newMember: CastMember = {
      id: `prop-${Date.now()}`,
      url: finalUrl,
      tag: 'front',
      name: `${selectedCharacter.name} + Prop`,
      profile: {
        identity: selectedCharacter.profile?.identity || selectedCharacter.name,
        wardrobe: selectedCharacter.profile?.wardrobe || "",
        accessories: selectedProp?.prompt || "Injected Accessory",
        style: selectedCharacter.profile?.style || ""
      }
    };
    dispatch({ type: 'ADD_CAST', payload: newMember });
    dispatch({ type: 'ADD_LOG', payload: { message: "Added to cast library", type: 'success' } });
  };

  const handleSaveToActors = async () => {
    const finalUrl = processedApplyUrl || appliedImage;
    if (!finalUrl || !state.saveDirectoryHandle) return;
    try {
        const actorsDir = await state.saveDirectoryHandle.getDirectoryHandle('Actors', { create: true });
        const name = (selectedCharacter?.name || 'Actor').slice(0, 30).replace(/[^a-z0-9]/gi, '_');
        const filename = `Actor-Prop-${Date.now()}-${name}.png`;
        const fileHandle = await actorsDir.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        const res = await fetch(finalUrl);
        const blob = await res.blob();
        await writable.write(blob);
        await writable.close();

        const newActor: CastMember = {
            id: `actor-prop-${Date.now()}`,
            url: finalUrl,
            tag: 'front',
            name: `${selectedCharacter?.name} + Prop`,
            profile: {
                identity: selectedCharacter?.profile?.identity || "Unknown",
                wardrobe: selectedCharacter?.profile?.wardrobe || "",
                accessories: selectedProp?.name || "Prop",
                style: "Prop Integration"
            }
        };
        dispatch({ type: 'ADD_ACTOR_LIBRARY', payload: newActor });
        dispatch({ type: 'ADD_LOG', payload: { message: `Saved to Actors Library: ${filename}`, type: 'success' } });
    } catch (e: any) {
        dispatch({ type: 'ADD_LOG', payload: { message: `Failed to save: ${e.message}`, type: 'error' } });
    }
  };

  return (
    <div className="h-full bg-[#0f0f11] flex overflow-hidden">
      <div className="w-80 border-r border-gray-800 bg-[#18181b] flex flex-col shadow-xl">
        <div className="p-4 border-b border-gray-800 flex justify-between items-center">
          <h2 className="text-sm font-black text-white tracking-widest uppercase">Prop Library</h2>
          <div className="flex gap-1.5">
            <label className="p-1.5 hover:bg-gray-700 rounded transition-colors text-gray-400 cursor-pointer">
              <Upload className="w-3.5 h-3.5" />
              <input type="file" className="hidden" accept="image/*" onChange={handleUploadProp} />
            </label>
            <button onClick={scanProps} className="p-1.5 hover:bg-gray-700 rounded transition-colors text-gray-400">
              <RefreshCcw className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
        
        <div className="flex-grow overflow-y-auto p-4 space-y-4">
          {!state.saveDirectoryHandle && (
            <div className="p-4 bg-yellow-500/5 border border-yellow-500/20 rounded-lg">
                <p className="text-[10px] text-yellow-500 font-bold leading-relaxed">
                    ⚠️ PLEASE SELECT A SAVE FOLDER IN SETTINGS TO ENABLE LOCAL PROP STORAGE.
                </p>
            </div>
          )}
          <div className="grid grid-cols-2 gap-2">
            {state.propItems.map(item => (
              <button 
                key={item.id}
                onClick={() => setSelectedProp(item)}
                className={`aspect-square rounded-lg border overflow-hidden transition-all group relative ${selectedProp?.id === item.id ? 'border-blue-500 border-2 shadow-lg shadow-blue-500/20' : 'border-gray-800 hover:border-gray-600'}`}
              >
                <img src={item.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <button onClick={(e) => { e.stopPropagation(); dispatch({ type: 'SET_INSPECT_IMAGE', payload: item.url }); }} className="bg-blue-500 text-white p-1.5 rounded-full"><Maximize className="w-3.5 h-3.5" /></button>
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="flex-grow flex flex-col bg-[#09090b]">
        <div className="flex bg-[#18181b] px-4 pt-4 gap-4 border-b border-gray-800">
          <button onClick={() => setActiveTab('designer')} className={`pb-3 px-4 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'designer' ? 'border-blue-500 text-blue-500' : 'border-transparent text-gray-500 hover:text-gray-300'}`}>Designer Workshop</button>
          <button onClick={() => setActiveTab('library')} className={`pb-3 px-4 text-xs font-bold uppercase tracking-widest border-b-2 transition-all ${activeTab === 'library' ? 'border-blue-500 text-blue-500' : 'border-transparent text-gray-500 hover:text-gray-300'}`}>Subject Application</button>
        </div>

        <div className="flex-grow overflow-y-auto p-8">
          {activeTab === 'designer' ? (
            <div className="max-w-4xl mx-auto grid grid-cols-2 gap-8">
                <div className="space-y-6">
                    <div className="bg-[#18181b] p-6 rounded-2xl border border-gray-800 shadow-xl">
                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 flex items-center gap-2"><Sparkles className="w-4 h-4 text-blue-500" /> Prop Designer</h3>
                        <textarea 
                            className="w-full bg-[#09090b] border border-[#27272a] p-4 rounded-xl text-sm text-gray-200 h-40 resize-none mb-4 focus:border-blue-500 focus:outline-none"
                            placeholder="Describe the prop or accessory..."
                            value={designerPrompt}
                            onChange={(e) => setDesignerPrompt(e.target.value)}
                        />
                        <button onClick={handleDesignerGenerate} disabled={state.isProcessing || !designerPrompt} className="w-full bg-blue-600 text-white py-3 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg active:scale-95 disabled:opacity-50">Generate Prop</button>
                    </div>
                </div>
                <div className="aspect-square bg-black rounded-2xl border border-gray-800 flex items-center justify-center overflow-hidden relative">
                    {designerImage ? (
                        <div className="relative w-full h-full">
                            <img src={designerImage} className="w-full h-full object-contain" />
                            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-3">
                                <button onClick={() => saveToProps(designerImage!, designerPrompt)} className="bg-blue-600 text-white px-8 py-3 rounded-full font-black text-[10px] uppercase flex items-center gap-3"><Package className="w-4 h-4" /> Save to Props</button>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col items-center opacity-20">
                            <Package className="w-16 h-16 mb-4" />
                            <span className="text-xs font-black uppercase tracking-widest">Awaiting Creation</span>
                        </div>
                    )}
                </div>
            </div>
          ) : (
            <div className="max-w-6xl mx-auto grid grid-cols-12 gap-8">
                <div className="col-span-4 space-y-6">
                    <div className="bg-[#18181b] p-6 rounded-2xl border border-gray-800 shadow-xl">
                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest border-b border-gray-800 pb-2">1. Selected Subject</h3>
                        <div className="grid grid-cols-4 gap-2 mb-6 h-32 overflow-y-auto p-2">
                            {state.cast.map(c => (
                                <button key={c.id} onClick={() => setSelectedCharacter(c)} className={`aspect-square rounded border transition-all overflow-hidden ${selectedCharacter?.id === c.id ? 'border-blue-500 ring-1 ring-blue-500' : 'border-gray-800 hover:border-gray-600'}`}><img src={c.url} className="w-full h-full object-cover" /></button>
                            ))}
                        </div>

                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest border-t border-gray-800 pt-6">2. Active Prop</h3>
                        <div className="aspect-square bg-[#09090b] rounded-xl border border-gray-800 mb-6 flex items-center justify-center overflow-hidden">
                            {selectedProp ? <img src={selectedProp.url} className="w-full h-full object-contain" /> : <Package className="w-10 h-10 opacity-10" />}
                        </div>

                        <h3 className="text-xs font-black text-gray-400 uppercase mb-4 tracking-widest border-t border-gray-800 pt-6">3. Placement Notes</h3>
                        <textarea className="w-full bg-[#09090b] border border-[#27272a] p-3 rounded-lg text-xs text-gray-300 h-20 mb-4 focus:border-blue-500 focus:outline-none" placeholder="Where should the prop be? (e.g. 'holding in right hand')..." value={applyNote} onChange={(e) => setApplyNote(e.target.value)} />
                        <button onClick={handleApply} disabled={state.isProcessing || !selectedCharacter || !selectedProp} className="w-full bg-blue-600 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 disabled:opacity-50">Apply to Character</button>
                    </div>
                </div>

                <div className="col-span-8">
                    <div className="aspect-square bg-black rounded-3xl border border-gray-800 flex items-center justify-center overflow-hidden relative">
                        {appliedImage ? (
                            <>
                                <img ref={applyImgRef} src={appliedImage} className={processedApplyUrl ? 'hidden' : 'w-full h-full object-cover'} />
                                {processedApplyUrl && <img src={processedApplyUrl} className="w-full h-full object-cover" />}
                                <canvas ref={applyCanvasRef} className="hidden" />
                                {applyMask && <img ref={applyMaskImgRef} src={applyMask} className="hidden" />}
                            </>
                        ) : (
                            <div className="flex flex-col items-center opacity-10">
                                <Package className="w-24 h-24 mb-6" />
                                <span className="text-sm font-black uppercase tracking-widest">Ready for Application</span>
                            </div>
                        )}
                        
                        {appliedImage && (
                            <div className="absolute top-6 right-6 flex flex-col gap-3 z-20 bg-black/60 p-4 rounded-3xl border border-white/10 backdrop-blur-md shadow-2xl">
                                <div className="flex items-center justify-between gap-6">
                                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            checked={removeApplyBg} 
                                            onChange={(e) => setRemoveApplyBg(e.target.checked)} 
                                            className="w-4 h-4 accent-blue-500 rounded" 
                                        />
                                        <Eraser className="w-3.5 h-3.5" /> Remove BG
                                    </label>

                                    {applyMask && (
                                        <label className="text-[9px] font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 cursor-pointer">
                                            <input 
                                                type="checkbox" 
                                                checked={applyAiMaskActive} 
                                                onChange={(e) => setApplyAiMaskActive(e.target.checked)} 
                                                className="w-3.5 h-3.5 accent-blue-500 rounded" 
                                            />
                                            <Sparkles className="w-3 h-3" /> AI Masking
                                        </label>
                                    )}
                                </div>
                                
                                {removeApplyBg && (
                                    <div className="space-y-3 pt-2 border-t border-white/5">
                                        <div className="flex items-center justify-between text-[9px] font-bold text-gray-500 uppercase tracking-wider">
                                            <span>Tolerance</span>
                                            <span>{applyTolerance}%</span>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="1" max="100" 
                                            value={applyTolerance} 
                                            onChange={(e) => setApplyTolerance(parseInt(e.target.value))}
                                            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                                        />

                                        {applyMask && applyAiMaskActive && (
                                            <>
                                                <div className="flex items-center justify-between text-[9px] font-bold text-blue-400/60 uppercase tracking-wider pt-1">
                                                    <span>Matte Contraction</span>
                                                    <span>{matteErosion}px</span>
                                                </div>
                                                <input 
                                                    type="range" 
                                                    min="0" max="10" 
                                                    step="1"
                                                    value={matteErosion} 
                                                    onChange={(e) => setMatteErosion(parseInt(e.target.value))}
                                                    className="w-full h-1 bg-blue-900/30 rounded-lg appearance-none cursor-pointer"
                                                />

                                                <div className="flex items-center justify-between text-[9px] font-bold text-blue-400/60 uppercase tracking-wider pt-1">
                                                    <span>Mask Softening</span>
                                                    <span>{applyMaskSoftening}px</span>
                                                </div>
                                                <input 
                                                    type="range" 
                                                    min="0" max="10" 
                                                    step="0.5"
                                                    value={applyMaskSoftening} 
                                                    onChange={(e) => setApplyMaskSoftening(parseFloat(e.target.value))}
                                                    className="w-full h-1 bg-blue-900/30 rounded-lg appearance-none cursor-pointer"
                                                />
                                            </>
                                        )}

                                        <div className="flex items-center justify-between text-[9px] font-bold text-green-400/60 uppercase tracking-wider pt-1">
                                            <span>Spill Suppression</span>
                                            <span>{applySpillSuppression}%</span>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="0" max="100" 
                                            value={applySpillSuppression} 
                                            onChange={(e) => setApplySpillSuppression(parseInt(e.target.value))}
                                            className="w-full h-1 bg-green-900/30 rounded-lg appearance-none cursor-pointer"
                                        />
                                        <div className="flex items-center justify-between pt-2 border-t border-white/5 mt-2">
                                            <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-2 cursor-pointer hover:text-gray-300 transition-colors pt-2">
                                                <input 
                                                    type="checkbox" 
                                                    checked={applyInvertBg} 
                                                    onChange={(e) => setApplyInvertBg(e.target.checked)} 
                                                    className="w-3.5 h-3.5 accent-red-500 rounded border-gray-700 bg-black/50"
                                                />
                                                Invert Matte
                                            </label>
                                            <div className="w-10 h-10 bg-black/60 border border-white/5 rounded-xl overflow-hidden shadow-inner flex items-center justify-center mt-2">
                                                <canvas ref={applyCanvasRef} className="max-w-full max-h-full object-contain scale-150" />
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {appliedImage && (
                            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex gap-4 z-30">
                                <button onClick={handleAddToCast} className="w-14 h-14 bg-emerald-500/20 text-emerald-500 rounded-xl flex items-center justify-center border border-emerald-500/30"><UserPlus className="w-6 h-6" /></button>
                                <button onClick={() => {
                                    const link = document.createElement('a');
                                    link.href = processedApplyUrl || appliedImage!;
                                    link.download = "applied-prop.png";
                                    link.click();
                                }} className="w-14 h-14 bg-white/10 text-white rounded-xl flex items-center justify-center border border-white/20"><Download className="w-6 h-6" /></button>
                                <button onClick={() => setAppliedImage(null)} className="w-14 h-14 bg-red-500/20 text-red-500 rounded-xl flex items-center justify-center border border-red-500/30"><X className="w-6 h-6" /></button>
                                <button onClick={handleSaveToActors} className="w-14 h-14 bg-indigo-500/20 text-indigo-500 rounded-xl flex items-center justify-center border border-indigo-500/30"><Save className="w-6 h-6" /></button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// --- 5. MAIN APP SHELL ---

const App = () => {
  const [state, dispatch] = useReducer(reducer, initialState);

  // Settings Modal State
  const [showSettings, setShowSettings] = useState(false);
  const [tempKey, setTempKey] = useState(state.apiKey);
  const [tempModel, setTempModel] = useState<AppState['model']>(state.model);

  const saveSettings = () => {
    dispatch({ type: 'SET_API_KEY', payload: tempKey });
    dispatch({ type: 'SET_MODEL', payload: tempModel });
    setShowSettings(false);
    dispatch({ type: 'ADD_LOG', payload: { message: "Settings saved", type: 'success' } });
  };

  // State Persistence Effect
  useEffect(() => {
    const persist = async () => {
        try {
            localStorage.setItem('nano_api_key', state.apiKey);
            localStorage.setItem('nano_model', state.model);
            localStorage.setItem('nano_director_v3', JSON.stringify(state.director));
            
            // Large assets go to IndexedDB to avoid QuotaExceededError
            await StorageService.save('nano_wardrobe', state.wardrobeItems);
            await StorageService.save('nano_actors', state.actorLibrary);
            await StorageService.save('nano_props', state.propItems);
        } catch (e: any) {
            console.error("Persistence failed", e);
        }
    };
    persist();
  }, [state.apiKey, state.model, state.director, state.wardrobeItems, state.actorLibrary, state.propItems]);

  // Initial Load from IndexedDB
  useEffect(() => {
    const restore = async () => {
        const actors = await StorageService.load<CastMember[]>('nano_actors', []);
        const wardrobe = await StorageService.load<WardrobeItem[]>('nano_wardrobe', []);
        const props = await StorageService.load<PropItem[]>('nano_props', []);
        if (actors.length > 0) dispatch({ type: 'SET_ACTOR_LIBRARY', payload: actors });
        if (wardrobe.length > 0) dispatch({ type: 'SET_WARDROBE_ITEMS', payload: wardrobe });
        if (props.length > 0) dispatch({ type: 'SET_PROP_ITEMS', payload: props });
    };
    restore();
  }, [dispatch]);

  // Sync Actors from Disk Handle (External Folder)
  useEffect(() => {
    const syncFromDisk = async () => {
      if (!state.saveDirectoryHandle) return;

      try {
        // dispatch({ type: 'ADD_LOG', payload: { message: "Scanning external actors folder...", type: 'info' } });
        
        let actorsDir;
        try {
          actorsDir = await state.saveDirectoryHandle.getDirectoryHandle('Actors', { create: false });
        } catch (e) {
          // Actors dir doesn't exist yet, nothing to sync
          return;
        }

        const externalActors: CastMember[] = [];
        // Iterate files
        // @ts-ignore - FileSystemDirectoryHandle is iterable in modern browsers
        for await (const entry of actorsDir.values()) {
          if (entry.kind === 'file' && entry.name.toLowerCase().endsWith('.png')) {
             try {
                // Parse filename: Actor-{index}-{safename}.png
                const nameParts = entry.name.match(/Actor-(\d+)-(.*)\.png/i);
                let displayName = entry.name.replace('.png', '');
                let identity = "Imported Actor";
                
                if (nameParts) {
                    // Cleaner name extraction
                    displayName = nameParts[2].replace(/_/g, ' '); 
                    identity = displayName;
                }

                // Deduplicate based on ID scheme
                const diskId = `disk-${entry.name}`;
                // Avoid re-reading if already in library
                // However, we can't easily check state inside async loop without updated ref or dependency
                // We'll filter later or hope state is fresh enough on mount

                const file = await entry.getFile();
                // Read as DataURL
                const reader = new FileReader();
                const dataUrl = await new Promise<string>((resolve) => {
                    reader.onload = (e) => resolve(e.target?.result as string);
                    reader.readAsDataURL(file);
                });

                externalActors.push({
                    id: diskId,
                    url: dataUrl,
                    tag: 'front', // Default for single files
                    name: displayName,
                    profile: {
                        identity: identity,
                        wardrobe: "",
                        accessories: "",
                        style: "External Asset"
                    }
                });
             } catch (err) {
                 console.warn("Failed to load actor file:", entry.name, err);
             }
          }
        }

        if (externalActors.length > 0) {
            // Functional update dispatch if possible, or just dispatch SET with merged list
            // Since we can't easily access latest 'state' inside this async closure if it's stale,
            // we rely on the specific dependency [state.saveDirectoryHandle] which implies this runs once per folder change.
            // But we should check duplicates against the *current* state at dispatch time.
            // We can pass a function to dispatch if it was setState, but here it's useReducer.
            // We will just dispatch a new action 'MERGE_ACTOR_LIBRARY' if it existed, or just SET.
            // I'll grab the latest state from the closure (it closed over state).
            // NOTE: If state.actorLibrary changes often, we might miss updates unless we include it in deps.
            // Inclusion in deps might cause loop.
            // Let's assume SET_ACTOR_LIBRARY is idempotent if we merge carefully.
            
            // To be safe, let's just dispatch ADD for each one? No, too many renders.
            // We will use SET_ACTOR_LIBRARY with a merge strategy.
            
            const existingIds = new Set(state.actorLibrary.map(a => a.id));
            const newOnes = externalActors.filter(a => !existingIds.has(a.id));
            
            if (newOnes.length > 0) {
                 const merged = [...state.actorLibrary, ...newOnes];
                 dispatch({ type: 'SET_ACTOR_LIBRARY', payload: merged });
                 dispatch({ type: 'ADD_LOG', payload: { message: `Imported ${newOnes.length} actors from disk.`, type: 'success' } });
            }
        }

      } catch (e: any) {
        console.error("Disk sync error:", e);
        dispatch({ type: 'ADD_LOG', payload: { message: `Disk scan failed: ${e.message}`, type: 'error' } });
      }
    };
    
    if (state.saveDirectoryHandle) {
        syncFromDisk();
    }
  }, [state.saveDirectoryHandle, state.actorLibrary.length]); // Re-run if folder changes or library size changes (to allow re-sync)

  return (
    <AppContext.Provider value={{ state, dispatch }}>
      <div className="flex flex-col h-screen bg-[#0f0f11] text-gray-200 font-sans selection:bg-yellow-500/30">
        
        {/* Header */}
        <header className="h-20 border-b border-white/5 bg-[#18181b] flex items-center justify-between px-6 z-50 shadow-2xl">
          <div className="flex items-center gap-3">
            <div className="relative flex items-center justify-center p-0.5 bg-white/5 rounded-lg border border-white/5 shadow-inner">
              <img 
                src={`data:image/png;base64,${LOGO_BASE64}`}
                alt="Branding Logo" 
                className="w-11 h-11 object-contain drop-shadow-[0_0_8px_rgba(234,179,8,0.4)] hover:scale-105 transition-all duration-300 cursor-pointer"
              />
            </div>
            <div className="flex flex-col gap-0.5">
              <h1 className="font-black text-xl tracking-tight leading-none flex items-center gap-2 whitespace-nowrap">
                <span className="text-white">NANO</span>
                <span className="text-yellow-500">BANANA</span>
                <span className="text-white">CAST DIRECTOR</span>
                <span className="text-yellow-500">STUDIO</span>
              </h1>
              <p className="text-[10px] font-black text-zinc-500 tracking-[0.3em] uppercase opacity-60">
                CAST · WARDROBE · STAGE · ACTION
              </p>
            </div>
          </div>

          <nav className="flex bg-[#09090b] p-1 rounded-lg border border-[#27272a]">
            {(['forge', 'wardrobe', 'props', 'blocking', 'production', 'veo'] as ViewMode[]).map(mode => (
              <button
                key={mode}
                onClick={() => dispatch({ type: 'SET_VIEW', payload: mode })}
                className={`px-4 py-1.5 rounded text-xs font-bold uppercase transition-all flex items-center gap-2 ${state.view === mode ? 'bg-[#27272a] text-white shadow-sm' : 'text-gray-500 hover:text-gray-300'}`}
              >
                {mode === 'veo' ? (
                  <>
                    STORYBOARD
                    <Clapperboard className={`w-3.5 h-3.5 ${state.view === 'veo' ? 'text-yellow-500' : 'text-yellow-600/50'}`} />
                  </>
                ) : mode === 'forge' ? 'CAST' : mode === 'blocking' ? 'STAGING' : mode === 'props' ? 'PROPS' : mode}
              </button>
            ))}
          </nav>

          <button onClick={() => setShowSettings(true)} className="text-gray-400 hover:text-white transition-colors">
            <Settings className="w-5 h-5" />
          </button>
        </header>

        {/* Main Content Area */}
        <main className="flex-grow overflow-hidden relative">
          {state.view === 'forge' && <CastingForge />}
          {state.view === 'wardrobe' && <WardrobeStudio />}
          {state.view === 'props' && <PropAccessoryStudio />}
          {state.view === 'blocking' && <SceneCanvas />}
          {state.view === 'production' && <ProductionConsole />}
          {state.view === 'veo' && <VeoGenerator />}
        </main>

        {/* Cinematic Loading Overlay */}
        {state.isProcessing && <NanobananaThinking />}
        <ImageInspector />

        {/* Footer / Logs */}
        <footer className="h-8 border-t border-[#27272a] bg-black flex items-center px-4 text-[10px] font-mono justify-between">
          <div className="flex items-center gap-4 text-gray-500">
             <span>ARCH: REACT_SPA</span>
             <span>MODE: {state.apiKey ? 'PRO (API ACTIVE)' : 'DEMO (SIMULATION)'}</span>
          </div>
          <div className="flex items-center gap-2">
             {state.logs.length > 0 && (
               <span className={`${state.logs[state.logs.length-1].type === 'error' ? 'text-red-500' : 'text-green-500'}`}>
                 {state.logs[state.logs.length-1].message}
               </span>
             )}
          </div>
        </footer>

        {/* Settings Modal */}
        {showSettings && (
          <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[100] flex items-center justify-center">
            <div className="bg-[#18181b] border border-gray-700 p-6 rounded-xl w-96 shadow-2xl animate-in fade-in zoom-in duration-200">
              <h2 className="text-lg font-bold text-white mb-4">Configuration</h2>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Gemini API Key</label>
                  <input 
                    type="password" 
                    className="w-full bg-[#09090b] border border-[#27272a] p-2 rounded text-sm text-white focus:border-yellow-500 focus:outline-none"
                    placeholder="AIzaSy..." 
                    value={tempKey}
                    onChange={(e) => setTempKey(e.target.value)}
                  />
                  <p className="text-[10px] text-gray-500 mt-2">
                    Required for the Service Layer to connect to Google Cloud. If empty, the app runs in Simulation Mode.
                  </p>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Render Save Folder</label>
                  <div className="flex gap-2">
                    <button 
                      onClick={async () => {
                        try {
                          const handle = await (window as any).showDirectoryPicker();
                          dispatch({ type: 'SET_SAVE_DIRECTORY', payload: handle });
                          dispatch({ type: 'ADD_LOG', payload: { message: `Save folder set: ${handle.name}`, type: 'success' } });
                        } catch (e: any) {
                          if (e.name !== 'AbortError') {
                            dispatch({ type: 'ADD_LOG', payload: { message: `Failed to set folder: ${e.message}`, type: 'error' } });
                          }
                        }
                      }}
                      className="flex-1 bg-gray-800 hover:bg-gray-700 text-white py-2 rounded text-xs font-bold transition-colors border border-gray-700"
                    >
                      {state.saveDirectoryHandle ? `Folder: ${state.saveDirectoryHandle.name}` : 'Choose Save Folder...'}
                    </button>
                    {state.saveDirectoryHandle && (
                      <button 
                        onClick={() => dispatch({ type: 'SET_SAVE_DIRECTORY', payload: null })}
                        className="bg-red-500/10 hover:bg-red-500/20 text-red-500 px-3 py-2 rounded text-xs transition-colors border border-red-500/30"
                        title="Reset folder (use browser downloads)"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                  <p className="text-[10px] text-gray-500 mt-2">
                    When set, rendered photos will save directly to this location.
                  </p>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-2 tracking-wider">Active Engine</label>
                  <div className="grid grid-cols-1 gap-2">
                    {[
                      { id: 'gemini-2.5-flash-image', name: 'Gemini 2.5 Flash (Image)', desc: 'Optimized for efficient image creation' },
                      { id: 'gemini-3-pro-image-preview', name: 'Gemini 3 Pro (Vision Ultra)', desc: 'Advanced reasoning & high-fidelity output' },
                      { id: 'imagen-4.0-generate-001', name: 'Imagen 4.0 (Legacy)', desc: 'Text-to-image focus' }
                    ].map(m => (
                      <button
                        key={m.id}
                        onClick={() => setTempModel(m.id as any)}
                        className={`text-left p-3 rounded-lg border transition-all ${tempModel === m.id ? 'bg-yellow-500/10 border-yellow-500 shadow-lg shadow-yellow-500/5' : 'bg-[#09090b] border-[#27272a] hover:border-gray-600'}`}
                      >
                        <div className="flex justify-between items-center mb-1">
                          <span className={`text-xs font-bold ${tempModel === m.id ? 'text-yellow-500' : 'text-gray-200'}`}>{m.name}</span>
                          {tempModel === m.id && <div className="w-2 h-2 rounded-full bg-yellow-500 shadow-[0_0_8px_rgba(234,179,8,0.6)]"></div>}
                        </div>
                        <p className="text-[10px] text-gray-500">{m.desc}</p>
                      </button>
                    ))}
                  </div>
                </div>
                <div className="flex justify-end gap-2 mt-6">
                  <button onClick={() => setShowSettings(false)} className="px-4 py-2 text-gray-400 text-xs hover:text-white">Cancel</button>
                  <button onClick={saveSettings} className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded text-xs font-bold">Save Config</button>
                </div>
              </div>
            </div>
          </div>
        )}

      </div>
    </AppContext.Provider>
  );
};

export default App;
